import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode, TransitionRule, LogEntry } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  initError: string | null;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  switchHybridRole: () => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
  isActionable: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

const WORKFLOW_MATRIX: TransitionRule[] = [
  { from: Status.RECIBIDO, to: Status.DERIVACION, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.EJECUCION, allowedRoles: [UserRole.HEAD, UserRole.SUPERADMIN, UserRole.ADMIN], requiresAnalyst: true, checkAreaJurisdiction: true },
  { from: Status.EJECUCION, to: Status.FINALIZADO, allowedRoles: [UserRole.ANALYST, UserRole.HEAD, UserRole.ADMIN, UserRole.SUPERADMIN], checkAreaJurisdiction: true },
  { from: Status.RECIBIDO, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN] },
  { from: Status.DERIVACION, to: Status.FINALIZADO, allowedRoles: [UserRole.ADMIN, UserRole.SUPERADMIN, UserRole.HEAD], checkAreaJurisdiction: true },
  { from: Status.FINALIZADO, to: Status.RECIBIDO, allowedRoles: [UserRole.SUPERADMIN] },
  { from: Status.EJECUCION, to: Status.DERIVACION, allowedRoles: [UserRole.HEAD, UserRole.SUPERADMIN, UserRole.ADMIN], checkAreaJurisdiction: true },
  { from: Status.DERIVACION, to: Status.RECIBIDO, allowedRoles: [UserRole.HEAD, UserRole.ADMIN, UserRole.SUPERADMIN], checkAreaJurisdiction: true }
];

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [initError, setInitError] = useState<string | null>(null);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        setInitError("Fallo en la conexión con la base de datos local SISREQ.");
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    setGlobalFilterArea(user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN ? 'ALL' : (user.area as Area));
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const switchHybridRole = () => {
    if (!currentUser || currentUser.role !== UserRole.ADMIN || !currentUser.area) return;
    const isNowHead = activeRole === UserRole.ADMIN;
    setActiveRole(isNowHead ? UserRole.HEAD : UserRole.ADMIN);
    setGlobalFilterArea(isNowHead ? (currentUser.area as Area) : 'ALL');
  };

  const createAuditLog = useCallback((message: string): LogEntry => ({
    id: genId('LOG'),
    timestamp: new Date().toISOString(),
    message,
    actor: currentUser?.name || 'Sistema',
    role: activeRole || UserRole.ANALYST
  }), [currentUser, activeRole]);

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;
    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión inactiva.' };
    if (req.status === target) return { allowed: false, reason: 'Fase operativa redundante.' };

    const rule = WORKFLOW_MATRIX.find(r => r.from === req.status && r.to === target);

    if (!rule) return { allowed: false, reason: 'Transición no contemplada en la matriz técnica.' };

    if (!rule.allowedRoles.includes(activeRole)) {
        return { allowed: false, reason: `Privilegios insuficientes (Rol: ${activeRole}).` };
    }

    if (rule.checkAreaJurisdiction && ![UserRole.SUPERADMIN, UserRole.ADMIN].includes(activeRole)) {
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena a su área operativa.' };
        if (target === Status.FINALIZADO && activeRole === UserRole.ANALYST) {
           if (req.assignedAnalyst !== currentUser.name) return { allowed: false, reason: 'Sólo el responsable técnico puede cerrar.' };
        }
    }

    if (rule.requiresAnalyst && !req.assignedAnalyst) {
        return { allowed: false, reason: 'Falta designación de Responsable Técnico.' };
    }

    return { allowed: true };
  }, [currentUser, activeRole]);

  const isActionable = useCallback((req: RequestCard): boolean => {
    if (!activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN) return true;
    return Object.values(Status).some(s => s !== req.status && canUserTransition(req, s).allowed);
  }, [activeRole, canUserTransition]);

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();

    // Si el creador es Jefatura, el ticket se auto-deriva a su área (Status.DERIVACION)
    // para que sea visible en su tablero inmediatamente.
    const initialStatus = activeRole === UserRole.HEAD ? Status.DERIVACION : Status.RECIBIDO;
    const auditMessage = activeRole === UserRole.HEAD 
      ? `SISTEMA: Apertura y auto-derivación técnica a Jefatura de ${area}.`
      : `SISTEMA: Apertura de registro oficial SISREQ en Bandeja Central.`;

    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: initialStatus,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [createAuditLog(auditMessage)]
    };

    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      assignedAnalyst: newStatus === Status.RECIBIDO ? undefined : req.assignedAnalyst,
      isReturned: newStatus === Status.RECIBIDO ? true : (newStatus === Status.EJECUCION ? false : req.isReturned),
      logs: [...req.logs, createAuditLog(`FLUJO: Cambio de fase operativa a [${newStatus.toUpperCase()}]`)]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r).sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, createAuditLog(`RETORNO TÉCNICO: ${reason.trim()}`)]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r).sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, createAuditLog(`SISTEMA: ${analystName.toUpperCase()} designado como Responsable Técnico.`)]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, createAuditLog(message.trim())]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, createAuditLog('SISTEMA: Actualización manual de metadatos técnicos.')]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) throw new Error("Acceso restringido a Auditoría Master.");
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = { 
      id: genId('U'), name, email, role, area, password: pass, status: 'ACTIVE', joinedAt: new Date().toISOString() 
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, initError, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, switchHybridRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest, isActionable
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq debe usarse dentro de SisreqProvider');
  return context;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, User, Building, Clock, Save, Send, 
    RotateCcw, CheckCircle2, Hash, PlayCircle, Trash2,
    ShieldAlert, UserCheck, History, ClipboardList, PenTool,
    ShieldCheck, MapPin
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    deleteRequest,
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole,
    canUserTransition
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);

  const data = useMemo(() => requests.find(r => r.id === selectedRequestId), [requests, selectedRequestId]);

  const filteredLogs = useMemo(() => {
    if (!data) return [];
    return data.logs.filter(log => 
        log.message.startsWith('FLUJO:') || 
        log.message.startsWith('RETORNO TÉCNICO:') || 
        log.message.startsWith('NOTA TÉCNICA:') ||
        log.message.startsWith('SISTEMA:')
    );
  }, [data]);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
        setActionError(null);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data || !currentUser) return null;

  const handleClose = () => setSelectedRequestId(null);
  const isFinalized = data.status === Status.FINALIZADO;

  const handleTransition = async (targetStatus: Status) => {
    setActionError(null);
    try {
        await updateStatus(data.id, targetStatus);
        handleClose(); // Cierra el modal automáticamente tras éxito
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleReturnSubmit = async () => {
    if (!returnReason.trim()) {
        setActionError("Debe especificar justificación técnica.");
        return;
    }
    try {
        await returnRequest(data.id, returnReason);
        setShowReturnInput(false);
        setReturnReason('');
        handleClose(); // Cierra el modal automáticamente tras retorno
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleAssignAnalyst = async (analystName: string) => {
    try {
        await assignAnalyst(data.id, analystName);
        setShowAnalystSelect(false);
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleSaveChanges = async () => {
    if (editTitle.trim() && editDetail.trim()) {
        await updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleAddComment = async () => {
    if (newComment.trim()) {
        await addLog(data.id, `NOTA TÉCNICA: ${newComment.trim()}`);
        setNewComment('');
    }
  };

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    (u.status === 'ACTIVE' || !u.status)
  );

  const canDeriveUI = canUserTransition(data, Status.DERIVACION).allowed;
  const canExecuteUI = canUserTransition(data, Status.EJECUCION).allowed;
  const canFinalizeUI = canUserTransition(data, Status.FINALIZADO).allowed;
  const canEditUI = (activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN) && !isFinalized;
  const showReturnButton = (activeRole === UserRole.HEAD || activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && 
                          data.status !== Status.RECIBIDO && data.status !== Status.FINALIZADO;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" onClick={handleClose}></div>
      <div className={`relative bg-white rounded-2xl shadow-2xl w-full max-w-xl max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-8 ${isFinalized ? 'border-emerald-600' : 'border-slate-900'}`}>

        <div className="px-6 py-4 flex justify-between items-center shrink-0 bg-slate-50 border-b border-slate-100">
          <div className="flex items-center gap-3 min-w-0">
             <div className={`p-2 rounded-xl text-white shrink-0 shadow-md ${isFinalized ? 'bg-emerald-600' : 'bg-slate-900'}`}>
                {isFinalized ? <CheckCircle2 size={18} strokeWidth={2.5}/> : <ClipboardList size={18} strokeWidth={2.5} />}
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2 mb-0.5">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest shadow-sm ring-1 ring-black/5 ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status.toUpperCase()}
                    </span>
                    <span className="text-[9px] text-slate-400 font-mono font-black bg-white px-2 py-0.5 rounded border border-slate-200 flex items-center gap-1 uppercase">
                        #{data.id.split('-')[1]?.toUpperCase() || 'SYS'}
                    </span>
                </div>
                {isEditing ? (
                    <input value={editTitle} onChange={e => setEditTitle(e.target.value)} className="text-lg font-black text-slate-900 w-full bg-white border-b-2 border-indigo-600 outline-none uppercase tracking-tight" />
                ) : (
                    <h2 className="text-lg font-black text-slate-900 truncate uppercase tracking-tight leading-none">{data.title}</h2>
                )}
             </div>
          </div>
          <button onClick={handleClose} className="p-2 text-slate-300 hover:text-slate-900 transition-colors"><X size={20} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-white custom-scrollbar">
            <div className="space-y-3">
                <div className="flex items-center justify-between">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><PenTool size={12} className="text-indigo-600"/> ALCANCE TÉCNICO</label>
                    {canEditUI && !isEditing && <button onClick={() => setIsEditing(true)} className="text-[9px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100 hover:bg-indigo-100">EDITAR</button>}
                </div>
                {isEditing ? (
                    <textarea value={editDetail} onChange={e => setEditDetail(e.target.value)} className="w-full bg-slate-50 border border-indigo-100 p-4 rounded-xl text-sm text-slate-900 leading-relaxed outline-none min-h-[120px] font-bold" />
                ) : (
                    <div className="bg-slate-50 p-5 rounded-xl border border-slate-100 italic text-slate-600 text-xs leading-relaxed">"{data.detail}"</div>
                )}
                {isEditing && (
                    <div className="flex justify-end gap-3 pt-1">
                        <button onClick={() => setIsEditing(false)} className="px-3 py-1 text-[9px] font-black text-slate-400 uppercase">CANCELAR</button>
                        <button onClick={handleSaveChanges} className="bg-slate-900 text-white px-5 py-2 rounded-xl text-[9px] font-black uppercase shadow-md flex items-center gap-2 active:scale-95 transition-all"><Save size={14}/> GUARDAR</button>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl">
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">ORIGEN</p>
                    <p className="text-[11px] font-black text-slate-900 truncate uppercase">{data.requester}</p>
                </div>
                <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl">
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">UNIDAD</p>
                    <p className="text-[11px] font-black text-slate-900 uppercase">{data.area}</p>
                </div>
            </div>

            <div className="p-5 bg-indigo-50/50 border border-indigo-100 rounded-2xl flex items-center gap-5 relative">
                <div className={`w-11 h-11 rounded-xl flex items-center justify-center text-white font-black text-sm shadow-md ${data.assignedAnalyst ? 'bg-indigo-600' : 'bg-slate-300'}`}>
                    {data.assignedAnalyst ? data.assignedAnalyst.substring(0,2).toUpperCase() : '?'}
                </div>
                <div className="flex-1">
                    <p className="text-[8px] font-black text-indigo-400 uppercase tracking-widest mb-0.5">RESPONSABLE TÉCNICO</p>
                    <p className={`text-sm font-black uppercase tracking-tight ${data.assignedAnalyst ? 'text-slate-900' : 'text-slate-400 italic'}`}>{data.assignedAnalyst || 'Sin asignación'}</p>
                </div>
                {(activeRole === UserRole.HEAD || activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN) && data.status === Status.DERIVACION && (
                    <div className="relative">
                        <button onClick={() => setShowAnalystSelect(!showAnalystSelect)} className="bg-white border border-indigo-200 text-indigo-600 px-4 py-2 rounded-xl text-[9px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all shadow-sm">DESIGNAR</button>
                        {showAnalystSelect && (
                            <div className="absolute top-full right-0 mt-2 w-60 bg-white border border-slate-200 shadow-xl rounded-xl p-2 z-[70] animate-in slide-in-from-top-2">
                                {availableAssignees.length > 0 ? availableAssignees.map(u => (
                                    <button key={u.id} onClick={() => handleAssignAnalyst(u.name)} className="w-full text-left px-3 py-2 hover:bg-indigo-50 rounded-lg text-[10px] font-black text-slate-700 uppercase">{u.name}</button>
                                )) : <div className="px-3 py-2 text-[9px] text-slate-400 italic uppercase">Sin analistas activos</div>}
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="space-y-4 pt-4 border-t border-slate-100">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><History size={14} className="text-slate-900"/> ACTIVIDAD OPERATIVA</label>
                <div className="flex gap-2">
                    <input value={newComment} onChange={e => setNewComment(e.target.value)} placeholder="AÑADIR NOTA TÉCNICA..." className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 text-[10px] font-black uppercase outline-none focus:border-indigo-600" onKeyPress={e => e.key === 'Enter' && handleAddComment()} />
                    <button onClick={handleAddComment} disabled={!newComment.trim()} className="bg-slate-900 text-white p-2.5 rounded-xl disabled:opacity-20 hover:bg-black transition-all"><Send size={14}/></button>
                </div>
                <div className="space-y-3 pl-4 border-l-2 border-slate-100 ml-2 max-h-60 overflow-y-auto custom-scrollbar">
                    {filteredLogs.length > 0 ? [...filteredLogs].reverse().map(log => (
                        <div key={log.id} className="relative py-1">
                            <div className="absolute -left-[21px] top-3 w-2.5 h-2.5 rounded-full bg-white border-2 border-slate-200"></div>
                            <div className="bg-slate-50/50 p-3 rounded-xl border border-slate-100">
                                <div className="flex justify-between items-center mb-1">
                                    <span className="text-[9px] font-black text-slate-900 uppercase">{log.actor} <span className="text-slate-300 ml-1">[{log.role}]</span></span>
                                    <span className="text-[8px] text-slate-400 font-mono">{new Date(log.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                </div>
                                <p className="text-[10px] text-slate-600 font-bold uppercase leading-tight">{log.message}</p>
                            </div>
                        </div>
                    )) : <p className="text-[10px] text-center text-slate-300 uppercase tracking-widest py-4">Sin actividad</p>}
                </div>
            </div>
        </div>

        <div className="bg-slate-50 border-t border-slate-100 px-6 py-5 flex flex-col gap-4">
            {actionError && <div className="bg-red-50 p-2.5 rounded-lg text-red-600 text-[8px] font-black uppercase text-center border border-red-100 flex items-center justify-center gap-2 animate-bounce"><ShieldAlert size={12}/> {actionError}</div>}

            {showReturnInput && (
                <div className="flex items-center gap-2 bg-red-50 p-2 rounded-xl border border-red-100 animate-in slide-in-from-bottom-2">
                    <input autoFocus value={returnReason} onChange={e => setReturnReason(e.target.value)} placeholder="JUSTIFICACIÓN TÉCNICA..." className="flex-1 bg-white border border-red-200 px-3 py-2.5 rounded-lg text-[9px] font-black text-red-900 uppercase outline-none" />
                    <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-4 py-2.5 rounded-lg text-[9px] font-black uppercase shadow-sm">ENVIAR</button>
                    <button onClick={() => setShowReturnInput(false)} className="p-1 text-red-400"><X size={20}/></button>
                </div>
            )}

            <div className="flex items-center gap-3">
                {activeRole === UserRole.SUPERADMIN && <button onClick={() => { if(confirm('¿BORRAR EXPEDIENTE?')) { deleteRequest(data.id); handleClose(); }}} className="h-11 w-11 flex items-center justify-center text-slate-400 hover:text-red-600 bg-white border border-slate-200 rounded-xl transition-all"><Trash2 size={18}/></button>}
                <div className="flex-1 flex gap-2">
                    {showReturnButton && !showReturnInput && <button onClick={() => setShowReturnInput(true)} className="flex-1 px-4 h-11 bg-white border border-red-200 text-[9px] font-black text-red-600 rounded-xl uppercase flex items-center justify-center gap-2 hover:bg-red-50"><RotateCcw size={14}/> RETORNAR</button>}
                    {canDeriveUI && <button onClick={() => handleTransition(Status.DERIVACION)} className="flex-1 h-11 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 px-3"><UserCheck size={14}/> DERIVAR</button>}
                    {canExecuteUI && <button onClick={() => handleTransition(Status.EJECUCION)} className="flex-1 h-11 bg-amber-500 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-amber-600 px-3"><PlayCircle size={14}/> EJECUTAR</button>}
                    {canFinalizeUI && <button onClick={() => handleTransition(Status.FINALIZADO)} className="flex-1 h-11 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-emerald-700 px-3"><ShieldCheck size={14}/> FINALIZAR</button>}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
