                          const items = filteredRequests.filter(r => r.status === col.status);
                          const isDragActive = dragOverColumn === col.status;

                          return (
                              <div 
                                  key={col.status} 
                                  className={`flex-1 flex flex-col min-w-[300px] max-w-[380px] rounded-[2rem] transition-all duration-300 ${isDragActive ? 'bg-white shadow-2xl ring-4 ring-indigo-500/5 scale-[1.02]' : 'bg-transparent'}`} 
                                  onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                                  onDragLeave={() => setDragOverColumn(null)} 
                                  onDrop={(e) => handleDrop(e, col.status)}
                              >
                                  <div className="flex items-center justify-between px-6 py-4 bg-white border border-slate-200 rounded-3xl mb-6 shadow-sm">
                                      <div className="flex items-center gap-4">
