                          <div><MapPin size={12} className="inline mr-1"/> Área</div>
                          <div><Building2 size={12} className="inline mr-1"/> Solicitante</div>
                          <div><GitPullRequest size={12} className="inline mr-1"/> Fase Actual</div>
                          <div><User size={12} className="inline mr-1"/> Responsable</div>
                          <div><AlertCircle size={12} className="inline mr-1"/> Urgencia</div>
                          <div className="text-right">Ver</div>
                      </div>

                      {/* Table Body */}
                      <div className="divide-y divide-slate-50">
                          {filteredRequests.length > 0 ? filteredRequests.map((req) => (
                              <div 
                                  key={req.id} 
                                  onClick={() => setSelectedRequestId(req.id)}
                                  className="grid grid-cols-[80px_1fr_120px_120px_140px_140px_100px_60px] gap-4 px-8 py-5 items-center hover:bg-indigo-50/30 transition-all group cursor-pointer"
                              >
                                  {/* ID */}
                                  <div className="text-[10px] font-mono font-black text-slate-400 uppercase">
                                      #{req.id.split('-')[1]?.toUpperCase()}
                                  </div>

                                  {/* Título */}
                                  <div className="min-w-0">
                                      <div className="flex items-center gap-2 mb-0.5">
                                          {req.isReturned && (
                                              <span className="text-[7px] bg-red-600 text-white px-1.5 py-0.5 rounded-md font-black uppercase animate-pulse shrink-0">RETORNO</span>
                                          )}
                                          <div className="text-[11px] font-black text-slate-800 uppercase truncate group-hover:text-indigo-600 transition-colors">
                                              {req.title}
                                          </div>
                                      </div>
                                      <div className="text-[9px] text-slate-400 font-bold truncate italic">
                                          "{req.detail.substring(0, 60)}..."
                                      </div>
                                  </div>

                                  {/* Área */}
                                  <div>
                                      <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-2 py-1 rounded-lg border border-indigo-100 uppercase tracking-tight">
                                          {req.area}
                                      </span>
                                  </div>

                                  {/* Solicitante */}
                                  <div className="text-[10px] font-bold text-slate-600 truncate uppercase">
                                      {req.requester}
                                  </div>

                                  {/* Fase */}
                                  <div>
                                      <span className={`px-2.5 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest border ${STATUS_BADGE_COLORS[req.status]}`}>
                                          {req.status}
                                      </span>
                                  </div>

                                  {/* Responsable */}
                                  <div className="min-w-0">
                                      {req.assignedAnalyst ? (
                                          <div className="flex items-center gap-2">
                                              <div className="w-6 h-6 rounded-lg bg-slate-800 text-white flex items-center justify-center font-black text-[8px] shrink-0">
