                      {COLUMNS.map((col) => {
                          if (col.status === Status.RECIBIDO && activeRole !== UserRole.ADMIN && activeRole !== UserRole.SUPERADMIN) return null;

                          const items = filteredRequests.filter(r => r.status === col.status);
