import React, { useMemo, useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Status, Area, Priority, UserRole } from '../types';
import { 
    BarChart3, TrendingUp, CheckCircle2, Clock, 
    Activity, AlertTriangle, CalendarRange, ArrowRight,
    Briefcase, Zap, Layers, Filter, Target, Calendar, PieChart
} from 'lucide-react';

export const ReportsView: React.FC = () => {
  const { requests, users } = useSisreq();
  const [timeRange, setTimeRange] = useState<'Semanal' | 'Mensual' | 'Anual' | 'Todo'>('Mensual');

  const filteredRequests = useMemo(() => {
    if (timeRange === 'Todo') return requests;
    const now = new Date();
    return requests.filter(r => {
        const reqDate = new Date(r.createdAt);
        const diffTime = Math.abs(now.getTime() - reqDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (timeRange === 'Semanal') return diffDays <= 7;
        if (timeRange === 'Mensual') return diffDays <= 30;
        if (timeRange === 'Anual') return diffDays <= 365;
        return true;
    });
  }, [requests, timeRange]);

  const stats = useMemo(() => {
    const total = filteredRequests.length;
    const completed = filteredRequests.filter(r => r.status === Status.FINALIZADO).length;
    const pending = total - completed;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;
    const byStatus = [Status.RECIBIDO, Status.DERIVACION, Status.EJECUCION, Status.FINALIZADO].map(status => {
        const count = filteredRequests.filter(r => r.status === status).length;
        const percentage = total > 0 ? Math.round((count / total) * 100) : 0;
        return { name: status, count, percentage };
    });
    const completedItems = filteredRequests.filter(r => r.status === Status.FINALIZADO && r.finishedAt);
    let avgDays = 0;
    if (completedItems.length > 0) {
        const totalMs = completedItems.reduce((acc, curr) => {
            const start = new Date(curr.createdAt).getTime();
            const end = new Date(curr.finishedAt!).getTime();
            return acc + (end - start);
        }, 0);
        avgDays = Number((totalMs / (1000 * 60 * 60 * 24) / completedItems.length).toFixed(1));
    }
    const byPriority = Object.values(Priority).map(p => ({
        name: p,
        count: filteredRequests.filter(r => r.priority === p).length
    }));
    return { total, completed, pending, completionRate, byStatus, avgDays, byPriority };
  }, [filteredRequests]);

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10 bg-[#F8FAFC]">
        {/* Header Section Institucional */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
            <div className="flex flex-col gap-1">
                <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-slate-900 text-white rounded-xl shadow-xl">
                        <TrendingUp size={20} strokeWidth={2.5} />
                    </div>
                    <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase leading-none">Inteligencia Operativa</h3>
                </div>
                <div className="flex items-center gap-3 mt-1">
                    <span className="text-[9px] text-slate-400 font-black tracking-widest uppercase flex items-center gap-1.5 ml-1">
                        <Calendar size={12} className="text-indigo-400" /> CORTE TEMPORAL:
                    </span>
                    <span className="text-indigo-600 bg-indigo-50 px-2.5 py-0.5 rounded-lg border border-indigo-100 text-[9px] font-black uppercase tracking-tight">{timeRange}</span>
                </div>
            </div>

            <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-sm">
                {['Semanal', 'Mensual', 'Anual', 'Todo'].map((range) => (
                    <button
                        key={range}
                        onClick={() => setTimeRange(range as any)}
                        className={`px-5 py-2.5 text-[9px] font-black uppercase tracking-widest rounded-xl transition-all ${
                            timeRange === range 
                            ? 'bg-white text-indigo-600 shadow-lg ring-1 ring-black/5' 
                            : 'text-slate-400 hover:text-slate-800'
                        }`}
                    >
                        {range}
                    </button>
                ))}
            </div>
        </div>

        {/* High Density Stats Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {[
                { label: 'FLUJO TOTAL', val: stats.total, icon: <Briefcase size={20}/>, color: 'bg-slate-900', trend: 'TICKETS' },
                { label: 'ACTIVOS', val: stats.pending, icon: <Zap size={20}/>, color: 'bg-orange-500', trend: 'EJECUCIÓN' },
                { label: 'RESOLUCIÓN', val: `${stats.completionRate}%`, icon: <Target size={20}/>, color: 'bg-emerald-600', trend: 'EFICIENCIA' },
                { label: 'ANSI SLA', val: `${stats.avgDays}d`, icon: <Clock size={20}/>, color: 'bg-indigo-600', trend: 'PROMEDIO' }
            ].map((card, i) => (
                <div key={i} className="bg-white p-7 rounded-[2.5rem] border border-slate-200 shadow-xl shadow-slate-200/50 hover:-translate-y-1 transition-all duration-300 group">
                    <div className="flex items-center justify-between mb-8">
