                    </div>
                    <div>
                        <p className="text-4xl font-black text-slate-900 tracking-tighter leading-none">{card.val}</p>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] mt-3">{card.label}</p>
