                <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl">
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">GESTIÓN ÁREA</p>
                    <p className="text-[11px] font-black text-slate-900 uppercase">{data.area}</p>
                </div>
            </div>

            <div className="p-5 bg-indigo-50/50 border border-indigo-100 rounded-2xl flex items-center gap-5 relative">
                <div className={`w-11 h-11 rounded-xl flex items-center justify-center text-white font-black text-sm shadow-md ${data.assignedAnalyst ? 'bg-indigo-600' : 'bg-slate-300'}`}>
                    {data.assignedAnalyst ? data.assignedAnalyst.substring(0,2).toUpperCase() : '?'}
                </div>
                <div className="flex-1">
                    <p className="text-[8px] font-black text-indigo-400 uppercase tracking-widest mb-0.5">RESPONSABLE DESIGNADO</p>
                    <p className={`text-sm font-black uppercase tracking-tight ${data.assignedAnalyst ? 'text-slate-900' : 'text-slate-400 italic'}`}>{data.assignedAnalyst || 'Pendiente de asignación'}</p>
                </div>
                {(activeRole === UserRole.HEAD || activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN) && data.status === Status.DERIVACION && (
                    <div className="relative">
                        <button onClick={() => setShowAnalystSelect(!showAnalystSelect)} className="bg-white border border-indigo-200 text-indigo-600 px-4 py-2 rounded-xl text-[9px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all shadow-sm flex items-center gap-2">
                           <User size={12}/> ASIGNAR
                        </button>
                        {showAnalystSelect && (
                            <div className="absolute top-full right-0 mt-2 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl p-2 z-[70] animate-in slide-in-from-top-2">
                                <div className="px-3 py-1.5 text-[8px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 mb-1">Personal del Área {data.area}</div>
                                <div className="max-h-48 overflow-y-auto custom-scrollbar">
                                    {availableAssignees.length > 0 ? availableAssignees.map(u => (
                                        <button 
                                            key={u.id} 
                                            onClick={() => handleAssignAnalyst(u.name)} 
                                            className="w-full text-left px-3 py-2.5 hover:bg-indigo-50 rounded-xl transition-colors group/item"
                                        >
                                            <div className="flex items-center justify-between">
                                                <span className="text-[10px] font-black text-slate-700 uppercase group-hover/item:text-indigo-600">{u.name}</span>
                                                <span className={`text-[7px] font-black px-1.5 py-0.5 rounded-md border uppercase tracking-tighter ${
                                                    u.role === UserRole.HEAD ? 'bg-indigo-100 text-indigo-700 border-indigo-200' : 'bg-slate-100 text-slate-500 border-slate-200'
                                                }`}>
                                                    {u.role === UserRole.HEAD ? 'JEFATURA' : 'ANALISTA'}
                                                </span>
                                            </div>
                                        </button>
                                    )) : <div className="px-3 py-4 text-[9px] text-slate-400 italic uppercase text-center">No hay personal activo en esta unidad</div>}
                                </div>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="space-y-4 pt-4 border-t border-slate-100">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><History size={14} className="text-slate-900"/> LOG DE SEGUIMIENTO</label>
                <div className="flex gap-2">
                    <input value={newComment} onChange={e => setNewComment(e.target.value)} placeholder="AÑADIR COMENTARIO TÉCNICO..." className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 text-[10px] font-black uppercase outline-none focus:border-indigo-600 shadow-inner" onKeyPress={e => e.key === 'Enter' && handleAddComment()} />
                    <button onClick={handleAddComment} disabled={!newComment.trim()} className="bg-slate-900 text-white p-2.5 rounded-xl disabled:opacity-20 hover:bg-black transition-all shadow-md"><Send size={14}/></button>
                </div>
                <div className="space-y-3 pl-4 border-l-2 border-slate-100 ml-2 max-h-60 overflow-y-auto custom-scrollbar">
                    {filteredLogs.length > 0 ? [...filteredLogs].reverse().map(log => (
                        <div key={log.id} className="relative py-1">
                            <div className="absolute -left-[21px] top-3 w-2.5 h-2.5 rounded-full bg-white border-2 border-slate-200"></div>
                            <div className="bg-slate-50/50 p-3 rounded-xl border border-slate-100">
                                <div className="flex justify-between items-center mb-1">
                                    <span className="text-[9px] font-black text-slate-900 uppercase">{log.actor} <span className="text-slate-300 ml-1">[{log.role}]</span></span>
                                    <span className="text-[8px] text-slate-400 font-mono">{new Date(log.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                </div>
                                <p className="text-[10px] text-slate-600 font-bold uppercase leading-tight">{log.message}</p>
                            </div>
                        </div>
                    )) : <p className="text-[10px] text-center text-slate-300 uppercase tracking-widest py-4">Sin actividad registrada</p>}
                </div>
            </div>
        </div>

        <div className="bg-slate-50 border-t border-slate-100 px-6 py-5 flex flex-col gap-4">
            {actionError && <div className="bg-red-50 p-2.5 rounded-lg text-red-600 text-[8px] font-black uppercase text-center border border-red-100 flex items-center justify-center gap-2 animate-bounce"><ShieldAlert size={12}/> {actionError}</div>}

            {showReturnInput && (
                <div className="flex items-center gap-2 bg-red-50 p-2 rounded-xl border border-red-100 animate-in slide-in-from-bottom-2">
                    <input autoFocus value={returnReason} onChange={e => setReturnReason(e.target.value)} placeholder="JUSTIFICACIÓN TÉCNICA O MOTIVO DE DEVOLUCIÓN..." className="flex-1 bg-white border border-red-200 px-3 py-2.5 rounded-lg text-[9px] font-black text-red-900 uppercase outline-none shadow-inner" />
                    <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-4 py-2.5 rounded-lg text-[9px] font-black uppercase shadow-lg">RETORNAR</button>
                    <button onClick={() => setShowReturnInput(false)} className="p-1 text-red-400"><X size={20}/></button>
                </div>
            )}

            <div className="flex items-center gap-3">
                {activeRole === UserRole.SUPERADMIN && <button onClick={() => { if(confirm('¿ELIMINAR ESTE EXPEDIENTE DE FORMA PERMANENTE?')) { deleteRequest(data.id); handleClose(); }}} className="h-11 w-11 flex items-center justify-center text-slate-400 hover:text-red-600 bg-white border border-slate-200 rounded-xl transition-all shadow-sm"><Trash2 size={18}/></button>}
                <div className="flex-1 flex gap-2">
                    {showReturnButton && !showReturnInput && <button onClick={() => setShowReturnInput(true)} className="flex-1 px-4 h-11 bg-white border border-red-200 text-[9px] font-black text-red-600 rounded-xl uppercase flex items-center justify-center gap-2 hover:bg-red-50 transition-colors"><RotateCcw size={14}/> RETORNAR A CENTRAL</button>}
                    {canDeriveUI && <button onClick={() => handleTransition(Status.DERIVACION)} className="flex-1 h-11 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 px-3 transition-all"><UserCheck size={14}/> DERIVAR A UNIDAD</button>}
                    {canExecuteUI && <button onClick={() => handleTransition(Status.EJECUCION)} className="flex-1 h-11 bg-amber-500 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-amber-600 px-3 transition-all"><PlayCircle size={14}/> INICIAR EJECUCIÓN</button>}
                    {canFinalizeUI && <button onClick={() => handleTransition(Status.FINALIZADO)} className="flex-1 h-11 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-emerald-700 px-3 transition-all"><ShieldCheck size={14}/> CERRAR EXPEDIENTE</button>}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area, UserRole, Priority } from '../types';
import { 
    Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, 
    ChevronDown, LayoutGrid, ShieldAlert, FileStack, List, 
    Table, Clock, User, Building2, MapPin, AlertCircle, Eye,
    Hash
} from 'lucide-react';
import { PRIORITY_STYLES, STATUS_BADGE_COLORS } from '../constants';

type DisplayMode = 'kanban' | 'list';

export const Board: React.FC = () => {
  const { 
    requests, 
    updateStatus, 
    globalFilterArea, 
    setGlobalFilterArea, 
    activeRole, 
    canUserSeeRequest, 
    setSelectedRequestId 
  } = useSisreq();

  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [errorToast, setErrorToast] = useState<string | null>(null);
  const [displayMode, setDisplayMode] = useState<DisplayMode>('kanban');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');

    const req = requests.find(r => r.id === requestId);
    if (!req) return;

    if (req.status === targetStatus) return;

    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        setErrorToast(err.message);
        setTimeout(() => setErrorToast(null), 4000);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={18} strokeWidth={2.5}/>, color: 'bg-indigo-600', text: 'text-indigo-600', light: 'bg-indigo-50' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} strokeWidth={2.5}/>, color: 'bg-orange-500', text: 'text-orange-600', light: 'bg-orange-50' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={18} strokeWidth={2.5}/>, color: 'bg-amber-500', text: 'text-amber-600', light: 'bg-amber-50' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={18} strokeWidth={2.5}/>, color: 'bg-emerald-600', text: 'text-emerald-600', light: 'bg-emerald-50' }
  ];

  return (
    <div className="flex flex-col h-full relative overflow-hidden">
      {errorToast && (
          <div className="absolute top-20 left-1/2 -translate-x-1/2 z-[100] bg-red-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300">
              <ShieldAlert size={20} />
              <span className="text-[11px] font-black uppercase tracking-widest">{errorToast}</span>
          </div>
      )}

      {/* Header Board Section */}
      <div className="px-8 py-5 flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white border-b border-slate-200 z-20 shadow-sm">
          <div className="flex items-center gap-5">
             <div className="bg-slate-900 p-3 rounded-2xl text-white shadow-xl shadow-slate-200">
                <FileStack size={22} strokeWidth={2.5}/>
             </div>
             <div className="flex flex-col">
                 <div className="flex items-center gap-2 mb-1">
                    <span className="bg-indigo-50 text-indigo-600 px-2.5 py-1 rounded-lg text-[9px] font-black border border-indigo-100 uppercase tracking-widest">
                        FLUJO OPERATIVO
                    </span>
                    <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                 </div>
                 <h2 className="text-2xl font-black text-slate-900 tracking-tighter uppercase leading-none">Sistema de Requerimientos</h2>
             </div>
          </div>

          <div className="flex items-center gap-4">
             {/* Search */}
             <div className="relative group">
                <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Filtrar por ID, Título o Solicitante..." 
                    className="w-full min-w-[280px] pl-12 pr-4 py-3 text-sm font-bold bg-slate-50 border border-slate-200 rounded-2xl focus:bg-white focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-600 outline-none transition-all placeholder:text-slate-300 shadow-inner"
                />
             </div>

             {/* Mode Selector */}
             <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shrink-0">
                <button 
                  onClick={() => setDisplayMode('kanban')}
                  className={`p-2 rounded-xl transition-all ${displayMode === 'kanban' ? 'bg-white text-indigo-600 shadow-md ring-1 ring-black/5' : 'text-slate-400 hover:text-slate-600'}`}
                  title="Vista Tablero"
                >
                  <LayoutGrid size={18} strokeWidth={2.5}/>
                </button>
                <button 
                  onClick={() => setDisplayMode('list')}
                  className={`p-2 rounded-xl transition-all ${displayMode === 'list' ? 'bg-white text-indigo-600 shadow-md ring-1 ring-black/5' : 'text-slate-400 hover:text-slate-600'}`}
                  title="Vista Lista"
                >
                  <List size={18} strokeWidth={2.5}/>
                </button>
             </div>

             {/* Global Filter */}
             {(activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                <div className="relative">
                    <MapPin size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="pl-12 pr-10 h-[48px] text-[10px] font-black bg-slate-50 border border-slate-200 rounded-2xl appearance-none cursor-pointer outline-none focus:border-indigo-600 transition-all uppercase tracking-widest text-slate-700 shadow-inner"
                    >
                        <option value="ALL">JURISDICCIÓN GLOBAL</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a.toUpperCase()}</option>)}
                    </select>
                    <ChevronDown size={16} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      {/* Content Area with Unified Transitions */}
      <div className="flex-1 overflow-hidden bg-[#F8FAFC]">
          {displayMode === 'kanban' ? (
              <div className="h-full overflow-x-auto overflow-y-hidden hide-scrollbar animate-in fade-in slide-in-from-bottom-3 duration-500">
                  <div className="h-full flex px-8 py-10 gap-8 min-w-[1300px]">
                      {COLUMNS.map((col) => {
                          if (col.status === Status.RECIBIDO && activeRole !== UserRole.ADMIN && activeRole !== UserRole.SUPERADMIN) return null;

                          const items = filteredRequests.filter(r => r.status === col.status);
                          const isDragActive = dragOverColumn === col.status;

                          return (
                              <div 
                                  key={col.status} 
                                  className={`flex-1 flex flex-col min-w-[300px] max-w-[380px] rounded-[2rem] transition-all duration-300 ${isDragActive ? 'bg-white shadow-2xl ring-4 ring-indigo-500/5 scale-[1.02]' : 'bg-transparent'}`} 
                                  onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                                  onDragLeave={() => setDragOverColumn(null)} 
                                  onDrop={(e) => handleDrop(e, col.status)}
                              >
                                  <div className="flex items-center justify-between px-6 py-4 bg-white border border-slate-200 rounded-3xl mb-6 shadow-sm">
                                      <div className="flex items-center gap-4">
                                          <div className={`p-2.5 rounded-2xl text-white shadow-lg ${col.color}`}>{col.icon}</div>
                                          <div className="flex flex-col">
                                              <span className="text-[11px] font-black uppercase tracking-widest text-slate-800">{col.title}</span>
                                              <span className={`text-[8px] font-black uppercase tracking-[0.2em] ${col.text}`}>FASE OPERATIVA</span>
                                          </div>
                                      </div>
                                      <span className="bg-slate-100 text-slate-500 px-3 py-1 rounded-xl text-[11px] font-black border border-slate-200">{items.length}</span>
                                  </div>

                                  <div className="flex-1 overflow-y-auto px-1 pb-20 hide-scrollbar space-y-5">
                                      {items.map(req => <RequestCard key={req.id} data={req} />)}
                                      {items.length === 0 && (
                                          <div className="flex flex-col items-center justify-center h-48 border-4 border-dashed border-slate-200 rounded-[2.5rem] text-slate-300 opacity-50 bg-white/30 transition-all hover:bg-white/50">
                                              <Inbox size={32} className="mb-2" />
                                              <p className="text-[10px] font-black uppercase tracking-widest">Sin expedientes</p>
                                          </div>
                                      )}
                                  </div>
                              </div>
                          )
                      })}
                  </div>
              </div>
          ) : (
              /* INSTITUTIONAL LIST VIEW with same animation set */
              <div className="h-full overflow-y-auto custom-scrollbar p-8 animate-in fade-in slide-in-from-bottom-3 duration-500">
                  <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-xl shadow-slate-200/50 overflow-hidden flex flex-col min-w-[1000px]">
                      {/* Institutional Table Header */}
                      <div className="grid grid-cols-[80px_1fr_120px_120px_140px_140px_100px_60px] gap-4 px-8 py-6 bg-slate-50/80 border-b border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] items-center">
                          <div><Hash size={12} className="inline mr-1 text-slate-300"/> ID</div>
                          <div><FileStack size={12} className="inline mr-1 text-slate-300"/> Expediente Técnico</div>
                          <div><MapPin size={12} className="inline mr-1 text-slate-300"/> Área</div>
                          <div><Building2 size={12} className="inline mr-1 text-slate-300"/> Solicitante</div>
                          <div><GitPullRequest size={12} className="inline mr-1 text-slate-300"/> Fase Actual</div>
                          <div><User size={12} className="inline mr-1 text-slate-300"/> Responsable</div>
                          <div><AlertCircle size={12} className="inline mr-1 text-slate-300"/> Urgencia</div>
                          <div className="text-right">Detalle</div>
                      </div>

                      {/* Institutional Body Rows */}
                      <div className="divide-y divide-slate-50">
                          {filteredRequests.length > 0 ? filteredRequests.map((req) => (
                              <div 
                                  key={req.id} 
                                  onClick={() => setSelectedRequestId(req.id)}
                                  className="grid grid-cols-[80px_1fr_120px_120px_140px_140px_100px_60px] gap-4 px-8 py-5 items-center hover:bg-indigo-50/30 transition-all group cursor-pointer"
                              >
                                  <div className="text-[10px] font-mono font-black text-slate-400 uppercase group-hover:text-indigo-400 transition-colors">
                                      #{req.id.split('-')[1]?.toUpperCase()}
                                  </div>

                                  <div className="min-w-0">
                                      <div className="flex items-center gap-2 mb-0.5">
                                          {req.isReturned && (
                                              <span className="text-[7px] bg-red-600 text-white px-1.5 py-0.5 rounded-md font-black uppercase animate-pulse shrink-0 tracking-tighter shadow-sm">RETORNO</span>
                                          )}
                                          <div className="text-[11px] font-black text-slate-800 uppercase truncate group-hover:text-indigo-600 transition-colors tracking-tight">
                                              {req.title}
                                          </div>
                                      </div>
                                      <div className="text-[9px] text-slate-400 font-bold truncate italic opacity-70">
                                          "{req.detail.substring(0, 60)}..."
                                      </div>
                                  </div>

                                  <div>
                                      <span className="text-[9px] font-black text-indigo-600 bg-indigo-50/50 px-2.5 py-1 rounded-lg border border-indigo-100 uppercase tracking-tight">
                                          {req.area}
                                      </span>
                                  </div>

                                  <div className="text-[10px] font-bold text-slate-500 truncate uppercase">
                                      {req.requester}
                                  </div>

                                  <div>
                                      <span className={`px-2.5 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest border shadow-sm transition-all ${STATUS_BADGE_COLORS[req.status]}`}>
                                          {req.status}
                                      </span>
                                  </div>

                                  <div className="min-w-0">
